/**
 * @distilled.cloud/temporal — Temporal HTTP SDK for Effect.
 *
 * Two services:
 *
 * - WorkflowService (start, signal and query workflows) — served by every
 *   Temporal server; its operations are exported from the package root.
 * - Cloud Ops API (namespaces, users, API keys, …) — served only by
 *   Temporal Cloud; its operations live under `Temporal.cloud`.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Temporal from "@distilled.cloud/temporal";
 *
 * const ns = yield* Temporal.listNamespaces({});
 * const cloudNs = yield* Temporal.cloud.listNamespaces({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  TemporalProtocol,
  type TemporalOpError,
  type TemporalOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts — the ops actually raise the
// service-local classes.
export * from "./services/temporal.ts";
// Cloud Ops operations share names with WorkflowService ones
// (`listNamespaces`), so they stay namespaced.
export * as cloud from "./services/cloud.ts";
